#include <iostream>
using namespace std;

const long long MOD = 1000000007;

long long factorial(int n) {
    long long ans = 1;
    for(int i = 2; i <= n; i++) {
        ans = (ans * i) % MOD;
    }
    return ans;
}

int main() {
    long long int n;
    cin >> n;
    cout << factorial(n) << endl;
    return 0;
}

#include <iostream>
const long long MOD = 1000000007;

int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);

  long long int n;
  std::cin >> n;

  // Precompute factorials
  long long int factorials[n + 1];
  factorials[0] = 1;

  for(int i = 1; i <= n; i++) {
    factorials[i] = (factorials[i - 1] * i) % MOD;
  }

  std::cout << factorials[n] << std::endl;
  return 0;
}

